import { installShareSettings } from './share-settings.js';
import { installPocketMusic } from './pocket-music.js';
import { installMessagePasses } from './message-pass.js';
import { installComposer } from './composer.js';
import { installPhotoPrinter } from './photo-printer.js';
import { installPaperNote } from './paper-note.js';
import { installFolderHome } from './folder-home.js';
import { selectCharacterById, setActiveCharacter, setActiveGroup } from '../../../../script.js';
import { openGroupById } from '../../../group-chats.js';

const context = () => SillyTavern.getContext();

const root = document.documentElement;
let shell;
let revision = 0;
let opening = false;
const railSkin = "\n.ah-layout #top-settings-holder {\n    --ah-icon-slot: clamp(26px, min(5.5dvh, 9vw), 44px);\n    background:\n        linear-gradient(90deg, #fff9, transparent 24%, #fff9 70%, #b6a5e047),\n        radial-gradient(ellipse at 0% 12%, #dcccf6c9, transparent 55%),\n        linear-gradient(158deg, #f5efffd9, #fdf8f0bd 52%, #dcd8f2d4) !important;\n    border-right-color: #fff !important;\n    box-shadow: inset 1px 0 0 #fff, inset -2px 0 0 #fff9, 2px 0 10px #75629938 !important;\n}\n.ah-layout #top-settings-holder::before {\n    content: \"\" !important;\n    position: absolute;\n    inset: 0;\n    z-index: -1;\n    pointer-events: none;\n    backdrop-filter: blur(14px) saturate(140%);\n    -webkit-backdrop-filter: blur(14px) saturate(140%);\n}\n.ah-layout #top-settings-holder > .drawer :is(.drawer-toggle, .drawer-icon) {\n    display: grid;\n    place-items: center;\n}\n.ah-layout #top-settings-holder > .drawer .drawer-icon,\n.ah-layout #top-settings-holder > .drawer .drawer-icon:is(:hover,.openIcon) {\n    position: relative;\n    width: var(--ah-icon-slot) !important;\n    height: var(--ah-icon-slot) !important;\n    background: var(--ah-object, var(--tw-sticker)) center / contain no-repeat !important;\n    border: 0 !important;\n    border-radius: 0 !important;\n    box-shadow: none !important;\n}\n.ah-layout #top-settings-holder#top-settings-holder > .drawer .drawer-icon::before {\n    content: none !important;\n}\n.ah-layout #top-settings-holder#top-settings-holder > .drawer .drawer-icon:is(:hover,.openIcon)::before {\n    filter: drop-shadow(0 2px 2px #8268b57a);\n}\n.ah-layout #top-settings-holder > .drawer .drawer-icon.openIcon::after {\n    content: \"\" !important;\n    position: absolute;\n    left: -3px;\n    width: 3px;\n    height: 14px;\n    border-radius: 3px;\n    background: #8c73b9;\n}\n.ah-layout #top-settings-holder #ai-config-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #sys-settings-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #advanced-formatting-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #WI-SP-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #user-settings-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #backgrounds-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #extensions-settings-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #persona-management-button { --ah-object: url(\"data:image/png;base64,\"); }\n.ah-layout #top-settings-holder #rightNavHolder { --ah-object: url(\"data:image/png;base64,\"); }\n";
const wideLayout = matchMedia('(min-width: 760px)');
const sidebarPreference = 'after-hours:receipt-collapsed';
let desktopCollapsed = localStorage.getItem(sidebarPreference) !== 'false';

function element(tag, className, text) {
    const node = document.createElement(tag);
    node.className = className;
    if (text) node.textContent = text;
    return node;
}

function button(label, action, className = 'ah-button') {
    const node = element('button', className, label);
    node.type = 'button';
    node.addEventListener('click', action);
    return node;
}

function member(name, url) {
    const row = element('div', 'ah-member');
    if (url) {
        const image = element('img', 'ah-avatar');
        image.src = url;
        image.alt = '';
        row.append(image);
    } else {
        row.append(element('span', 'ah-avatar ah-initial', name.slice(0, 1)));
    }
    row.append(element('span', '', name));
    return row;
}

function mount() {
    const header = element('header', 'ah-header');
    const sidebar = element('aside', 'ah-channels');
    sidebar.setAttribute('aria-label', '最近对话');
    const people = element('aside', 'ah-members');
    people.setAttribute('aria-label', '当前对话成员');
    const title = element('strong', 'ah-title');
    const list = element('div', 'ah-list');
    const members = element('div', 'ah-member-list');
    const toggle = button('', () => {
        if (wideLayout.matches) {
            desktopCollapsed = !desktopCollapsed;
            localStorage.setItem(sidebarPreference, String(desktopCollapsed));
        } else {
            root.classList.toggle('ah-channels-open');
        }
        syncChannels();
    }, 'ah-clip');
    const clipImage = element('img', '');
    clipImage.alt = '';
    clipImage.src = "data:image/png;base64,";
    toggle.append(clipImage);
    toggle.setAttribute('aria-controls', 'ah-channels');
    sidebar.id = 'ah-channels';
    header.append(element('span', 'ah-hash', '#'), title);
    const back = element('div', 'ah-receipt-back');
    back.setAttribute('aria-hidden', 'true');
    back.innerHTML = '<svg viewBox="0 0 40 112" fill="none" stroke="#877496" stroke-width="1"><path d="M12 106Q34 74 26 11"/><path d="M27 32Q9 27 15 11Q26 16 27 32M28 46Q44 40 37 24Q27 30 28 46M27 61Q8 55 11 40Q26 44 27 61M24 74Q43 70 39 53Q27 56 24 74M18 91Q3 82 5 68Q20 72 18 91"/></svg>';
    const receipt = element('div', 'ah-receipt');
    receipt.append(element('div', 'ah-brand', 'MOI'), list, element('div', 'ah-receipt-foot', 'Continue...'));
    sidebar.append(back, receipt);

    const style = element('style', '');
    style.textContent = `
        .ah-layout .ah-header .ah-toggle {
            display: inline-grid;
            place-items: center;
            min-width: 34px;
            min-height: 34px;
        }
        @media (min-width: 760px) {
            .ah-layout.ah-channels-collapsed .ah-channels { display: none; }
            .ah-layout.ah-channels-collapsed :is(#sheld, .ah-header) {
                left: var(--tw-rail) !important;
            }
        }
    `;
    style.textContent += railSkin;
    style.textContent += ".ah-layout .ah-clip {\n    display: grid;\n    place-items: center;\n    position: fixed;\n    z-index: 3010;\n    left: calc(var(--tw-rail) - 12px);\n    top: max(33px, env(safe-area-inset-top));\n    width: 28px;\n    height: 43px;\n    padding: 0;\n    border: 0;\n    background: transparent;\n    cursor: pointer;\n    filter: drop-shadow(1px 2px 1px #42384b55);\n}\n.ah-clip svg { width: 20px; height: 37px; }\n.ah-clip:focus-visible { outline: 2px solid #8067ac; border-radius: 6px; }\n.ah-layout .ah-channels {\n    top: max(48px, calc(env(safe-area-inset-top) + 15px));\n    left: calc(var(--tw-rail) + 5px);\n    bottom: auto;\n    height: auto;\n    overflow: visible;\n    padding: 8px 22px 16px 3px;\n    border: 0;\n    background: transparent;\n    box-shadow: none;\n}\n.ah-layout.ah-channels-open .ah-channels { box-shadow: none; }\n.ah-receipt {\n    position: relative;\n    max-height: min(73dvh, 660px);\n    overflow: auto;\n    padding: 14px 10px 12px;\n    border: 1px solid #fff9;\n    border-radius: 3px 3px 6px 6px;\n    background: repeating-linear-gradient(115deg,#fff0 0 3px,#b3a1bf09 3px 4px),\n        linear-gradient(154deg,#fffdf7db,#f5eef9cb);\n    backdrop-filter: blur(9px);\n    box-shadow: 1px 4px 12px #61516e28;\n    font-family: ui-rounded, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n    color: #493f53;\n}\n.ah-receipt-back {\n    position: absolute;\n    inset: 13px 14px 23px 19px;\n    background: linear-gradient(135deg,#f6f0f8da,#e5d9eed9);\n    transform: rotate(6deg);\n    transform-origin: 70% 10%;\n    box-shadow: 1px 3px 8px #61516e25;\n    overflow: hidden;\n    pointer-events: none;\n}\n.ah-receipt-back svg { position: absolute; right: -5px; bottom: 8%; width: 37px; height: 106px; opacity: .64; }\n.ah-receipt .ah-brand {\n    height: auto;\n    padding: 3px 0 8px;\n    justify-content: center;\n    text-align: center;\n    font: 700 clamp(16px,2.1vw,24px)/1.1 \"Chalkboard SE\", \"Comic Sans MS\", cursive;\n    letter-spacing: .03em;\n    border-bottom: 1px dashed #c7b6ce;\n}\n.ah-receipt .ah-search { margin: 8px 0 4px; font: inherit; font-size: 12px; background: #fff6; }\n.ah-receipt .ah-label { margin: 6px 0; text-align: center; font-size: 11px; color: #65586f; }\n.ah-receipt .ah-channel {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    min-height: 31px;\n    padding: 4px 3px;\n    color: #493f53;\n    font-size: 13px;\n}\n.ah-receipt .ah-channel[hidden] { display: none; }\n.ah-receipt .ah-channel[aria-current=\"page\"] { background: #e6dbf4; color: #493477; }\n.ah-receipt .ah-channel-file, .ah-receipt .ah-channel .ah-hash { display: none; }\n.ah-receipt-foot { margin-top: 8px; padding-top: 7px; border-top: 1px dashed #c7b6ce; font-size: 10px; letter-spacing: .2em; }\n@media (max-width: 759px) {\n    .ah-layout .ah-channels { width: min(232px, calc(100vw - var(--tw-rail) - 8px)); }\n}\n\n/* Two translucent sheets with separate edges and visible overlap. */\n.ah-layout .ah-channels {\n    padding: 20px 32px 24px 7px;\n    width: calc(var(--ah-left) - 4px);\n}\n.ah-receipt {\n    max-height: min(68dvh, 570px);\n    padding: 19px 11px 14px;\n    border: 1px solid #fdfaffd9;\n    border-bottom-color: #d6cddb;\n    border-radius: 1px;\n    background: repeating-linear-gradient(0deg, #73657c0a 0 1px, transparent 1px 3px),\n        linear-gradient(145deg, #fffef2b8, #f4edf3a3);\n    backdrop-filter: blur(2px);\n    box-shadow: 0 1px 2px #51405920, 2px 5px 12px #51405926, inset 0 0 6px #fff8;\n}\n.ah-receipt-back {\n    inset: 15px 15px 27px 29px;\n    transform: rotate(-8deg);\n    transform-origin: 60% 14%;\n    border: 1px solid #cbbdd583;\n    background: repeating-linear-gradient(97deg, transparent 0 4px, #7765870d 4px 5px),\n        linear-gradient(158deg, #f0e9f3b3, #d9cbe7c9);\n    box-shadow: 2px 4px 7px #5f4a6e2c;\n}\n.ah-receipt-back svg { right: -2px; bottom: 7%; width: 48px; height: 145px; opacity: .82; }\n.ah-clip img { display: block; width: 23px; height: 42px; object-fit: contain; pointer-events: none; }\n.ah-clip { filter: drop-shadow(1px 2px 1px #40334040); }\n@media (max-width: 759px) {\n    .ah-layout .ah-channels { width: min(235px, calc(100vw - var(--tw-rail) - 10px)); }\n}\n\n.ah-clip img { transform: rotate(13deg); }\n\n/* Both sheets meet the fixed clip at their top left corner. */\n.ah-layout .ah-channels {\n    left: calc(var(--tw-rail) - 8px);\n    top: max(51px, calc(env(safe-area-inset-top) + 18px));\n    padding-top: 0;\n    padding-left: 0;\n}\n.ah-receipt { padding-top: 25px; }\n.ah-receipt-back {\n    top: 0;\n    left: 3px;\n    transform-origin: 12px 0;\n    transform: rotate(-7deg);\n}\n\n.ah-receipt .ah-channel, .ah-receipt-foot {\n    font-family: \"MOI Smile\", \"Kaiti SC\", \"STKaiti\", cursive;\n    font-weight: 400;\n    font-synthesis: none;\n}\n.ah-receipt .ah-channel-name { font-weight: 400; font-size: 15px; }\n.ah-receipt .ah-brand { margin-bottom: 11px; }\n.ah-receipt-foot { text-align: center; font-size: 13px; letter-spacing: .06em; color: #786780; }\n.ah-layout .ah-receipt {\n    scrollbar-width: thin;\n    scrollbar-color: #bca9ca88 transparent;\n}\n.ah-layout .ah-receipt::-webkit-scrollbar { width: 3px; height: 3px; }\n.ah-layout .ah-receipt::-webkit-scrollbar-track { background: transparent; border: 0; box-shadow: none; }\n.ah-layout .ah-receipt::-webkit-scrollbar-thumb {\n    border: 0;\n    border-radius: 6px;\n    background: #bca9ca88;\n    box-shadow: none;\n}\n.ah-layout .ah-receipt::-webkit-scrollbar-button { display: none; width: 0; height: 0; }\n";
    document.body.append(style, toggle, header, sidebar, people);
    return { title, list, members, toggle };
}

function syncChannels() {
    if (!shell) return;
    root.classList.toggle('ah-channels-collapsed', wideLayout.matches && desktopCollapsed);
    const open = wideLayout.matches ? !desktopCollapsed : root.classList.contains('ah-channels-open');
    const label = open ? '收起会话栏' : '展开会话栏';
    shell.toggle.setAttribute('aria-expanded', String(open));
    shell.toggle.setAttribute('aria-label', label);
    shell.toggle.title = label;
}

function closeChannels() {
    root.classList.remove('ah-channels-open');
    syncChannels();
}

async function openChat(chat) {
    if (opening) return;
    opening = true;
    try {
        const ctx = context();
        const file = chat.file_name.replace(/\.jsonl$/i, '');
        if (chat.group) {
            await openGroupById(chat.group);
            setActiveGroup(chat.group);
            if (context().getCurrentChatId() !== file) await ctx.openGroupChat(chat.group, file);
        } else {
            const id = ctx.characters.findIndex(character => character.avatar === chat.avatar);
            if (id < 0) return;
            await selectCharacterById(id, { switchMenu: false });
            setActiveCharacter(chat.avatar);
            if (context().getCurrentChatId() !== file) await ctx.openCharacterChat(file);
        }
        ctx.saveSettingsDebounced();
        closeChannels();
    } catch (error) {
        console.error('After Hours failed to open chat', error);
        toastr.error('无法打开这段对话');
    } finally {
        opening = false;
    }
}

async function refresh() {
    const current = ++revision;
    if (getComputedStyle(root).getPropertyValue('--ah-theme').trim() !== 'enabled') {
        root.classList.remove('ah-layout', 'ah-channels-open');
        return;
    }
    shell ??= mount();
    root.classList.add('ah-layout');
    syncChannels();
    const ctx = context();
    const character = ctx.characters[ctx.characterId];
    const group = ctx.groups.find(item => String(item.id) === String(ctx.groupId));
    const chatId = ctx.getCurrentChatId();
    shell.title.textContent = group?.name || character?.name || '欢迎来到 MOI';
    const selected = group
        ? (group.members || []).map(avatar => ctx.characters.find(item => item.avatar === avatar)).filter(Boolean)
        : character ? [character] : [];
    const userAvatar = document.querySelector('#chat > .mes[is_user="true"] .avatar img')?.getAttribute('src');
    shell.members.replaceChildren(...selected.map(item =>
        member(item.name, item.avatar && item.avatar !== 'none' ? ctx.getThumbnailUrl('avatar', item.avatar) : '')),
        member(ctx.name1 || '你', userAvatar));
    shell.list.replaceChildren(element('p', 'ah-empty', '正在读取对话…'));
    try {
        const response = await fetch('/api/chats/recent', {
            method: 'POST', headers: ctx.getRequestHeaders(),
            body: JSON.stringify({ max: 30, pinned: [] }),
        });
        if (!response.ok) throw new Error(String(response.status));
        const chats = await response.json();
        if (current !== revision) return;
        const rows = chats.flatMap(chat => {
            const entity = chat.group
                ? ctx.groups.find(item => String(item.id) === String(chat.group))
                : ctx.characters.find(item => item.avatar === chat.avatar);
            if (!entity || !chat.file_name) return [];
            const file = chat.file_name.replace(/\.jsonl$/i, '');
            const row = button('', () => openChat(chat), 'ah-channel');
            row.title = file;
            row.append(element('span', 'ah-hash', '#'), element('span', 'ah-channel-name', entity.name),
                element('small', 'ah-channel-file', file));
            const sameEntity = chat.group ? String(group?.id) === String(chat.group) : !group && character?.avatar === chat.avatar;
            if (sameEntity && file === chatId) row.setAttribute('aria-current', 'page');
            return [row];
        });
        shell.list.replaceChildren(...(rows.length ? rows : [element('p', 'ah-empty', '还没有最近对话')]));
    } catch (error) {
        if (current === revision) shell.list.replaceChildren(element('p', 'ah-empty', '暂时无法读取最近对话'));
        console.warn('After Hours recent chats', error);
    }
}

const { eventSource, eventTypes } = context();
for (const event of ['APP_READY', 'CHAT_CHANGED', 'CHARACTER_EDITED', 'PERSONA_CHANGED']) {
    eventSource.on(eventTypes[event], refresh);
}
new MutationObserver(() => {
    if (root.classList.contains('ah-layout') !== (getComputedStyle(root).getPropertyValue('--ah-theme').trim() === 'enabled')) {
        void refresh();
    }
}).observe(document.head, { childList: true, subtree: true, characterData: true });
wideLayout.addEventListener('change', closeChannels);
document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && root.classList.contains('ah-channels-open')) closeChannels();
});
void refresh();

installFolderHome();

installPaperNote();

installPhotoPrinter();
void installPocketMusic();

installComposer();

installMessagePasses();

installShareSettings();
